{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "The closest analogue, an amino-adamantane derivative, has 98% absolute oral bioavailability in humans, directly supporting high F for the adamantane primary amine query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Vildagliptin, which contains an adamantylglycine moiety, has approximately 85% absolute oral bioavailability in humans, showing that adamantane-containing drugs are well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Saxagliptin, another adamantyl-containing drug, has 50% absolute oral bioavailability in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "LY354740 has low human bioavailability, but it is a zwitterionic amino dicarboxylic acid with very different permeability characteristics from the lipophilic primary amine query, so this low-F evidence has limited transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "ABT-384 has model-estimated F of 18.1%, but its large adamantane carboxamide/piperazine-aryl structure is much more complex than the small primary amine query, limiting transferability of this low value.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is 1-adamantanamine (amantadine), a small lipophilic primary amine. The closest amino-adamantane analogue has 98% human oral bioavailability, and adamantane-containing drugs vildagliptin and saxagliptin have 85% and 50% F, respectively. Low-F analogues are polar acids or large complex molecules with poor transferability. Therefore F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for amantadine itself is included in the evidence set.",
    "The highest-similarity record (C06) has a SMILES/name inconsistency, adding some uncertainty.",
    "Morgan similarity scores are modest (<0.36), so structural transfer relies on shared adamantane/amine features rather than high overall similarity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

